  }
  export interface Actions<S extends string> {
    create<T2, S2 extends string>(lane: Lane<T2, S2>, data: T2, key?: string): Effect;
    move(state: S): Effect;
    remember<M>(library: Library<M>, draft: MemoryDraft<M>): Effect;
