  .scheduler(opsScheduler)
  .clients(controlApi)
  .observers(
    slack.notifier('incident-notifier', { webhookUrl: H.env('OPS_SLACK_WEBHOOK'), lanes: [incidentLane] }),
    markdown.board({ path: 'BOARD.md' }),
  );

