  .input(z.object({ incident: z.string(), service: z.string().optional() }))
  .argv(i => ['./ops/runbook.sh', i.incident, i.service ?? 'none'])
  .on(local);

const heartbeatFlow = H.flow('heartbeat').for(Heartbeat).does(async ctx => {
  await ctx.move('checking');
