  await ctx.move('checking');
  const expiry = await ctx.run(certificateExpiry, ctx.unit.data);
  if (!expiry.ok) return ctx.fail(expiry.error);
  if (expiry.value.daysLeft >= 14) return 'still-valid';
  await ctx.move('renewing');
