function tenancySupply(body: z.infer<typeof billingEvent>): SupplyOf<typeof Tenancy> {
  switch (body.event) {
    case 'signed-up':
      return { create: { customer: body.customer, plan: body.plan }, key: body.customer };
    case 'suspended':
