  .ledger(sqlite.ledger('lifecycles/ledger.db'))
  .lanes(experiments, tenancies, negotiations)
  .pools(H.pool('analysis', [{ account: anthropic.account('analysis', { apiKey: H.env('ANTHROPIC_API_KEY') }), share: 1 }]))
