    d.status === 'ready'
      ? { create: { cmsId: d.id, title: d.title, section: d.section, body: d.body, notes: '' }, key: d.id }
      : { update: d.id, patch: { body: d.body, notes: '' }, state: 'queued' }
  ),
});

