const crmEvents = webhook.json('crm-events', {
  port: H.slot.port(1),
  path: '/crm',
  secret: H.env('CRM_WEBHOOK_SECRET'),
  payload: z.object({
    event: z.enum(['signed', 'suspended', 'reinstated', 'churned']),
    customerId: z.string(),
    plan: z.string(),
