    })),
  ])
  .store(linear.store(Epic, { ...tracker, status: { EpicOpen: 'Todo', EpicDone: 'Done', EpicIncomplete: 'Canceled' } }))
  .runner(worktrees)
  .handler(epicFlow, {
    states: { complete: EpicDone, incomplete: EpicIncomplete, failed: EpicOpen },
