      rank:
        x.entry.lane === heartbeatLane.name
          ? 0
          : x.entry.lane === featureLane.name && x.waitedMs > starvationMs
            ? 1
            : x.entry.lane === bugLane.name
              ? 2
              : x.entry.lane === featureLane.name
